    <FilterList title="Filters on this page" filters={page.filters||[]} model={model} onAdd={f=>updatePage(p=>p.filters=[...(p.filters||[]),f])} onRemove={i=>updatePage(p=>p.filters=(p.filters||[]).filter((_,j)=>i!==j))}/>
